-- =============================================================================
-- 业务异常预警中心-异常规则初始化数据（platform_exception_rule，实际业务口径 6 条）
-- 来源：bea/rules-practical/*.yaml（exception geelato/v1，$gl.sql.query，已按 ob 实际表核校）
-- 生成：bea/rules-practical/_gen_init_sql.py（重跑重新生成，请勿手工修改）
-- 幂等：先按 rule_code 清理再插入，可重复执行；id 由雪花算法生成（重跑会变化，幂等靠 rule_code 清理保证）。
-- enable_status=0（1 生效 / 0 未启用，可用脚本参数调整；含待校准参数默认 0，见 README）。
-- app_id/tenant_code 等归属列未写死，按环境需要自行 UPDATE。
-- =============================================================================
SET NAMES utf8mb4;

-- 幂等清理（含历史逻辑删除行，避免 uk_exc_rule_code 冲突）
DELETE FROM `platform_exception_rule` WHERE `rule_code` IN (
  'EXC-BL-015', 'EXC-BL-016', 'EXC-CUS-001', 'EXC-FIN-018',
  'EXC-ODR-001', 'EXC-ODR-018'
);

INSERT INTO `platform_exception_rule`
  (`id`, `rule_code`, `rule_name`, `domain_code`, `rule_desc`, `level`, `rule_kind`, `escalation_of_rule_code`, `trigger_type`, `cron_expression`, `listen_entities`, `pipeline_json`, `threshold_json`, `owner_selector`, `resolve_policy`, `storm_json`, `biz_type`, `mutual_exclusive_group`, `flow_template`, `biz_url_template`, `enable_status`, `engine_version`, `version`, `seq_no`, `creator`, `creator_name`) VALUES
('371596548045410304', 'EXC-BL-015', '未收款放单', 'BL', '判定：提单已放单（il_order_bol.bol_status IN (''2'',''3'',''4'')——2正常/3异常/4担保放单），该订单应收未核销 > 0（费用行 il_so_container_fee_detail fee_type=''1'' 且 amount_not_written_off>0），且放单后 > 7 天。\n放单时点取 il_order_bol_grant.biz_status_time（该订单放单申请业务状态时间），无 grant 记录时兜底 il_order_bol.update_at。\n口径：未核销>0 以费用行聚合判定（账单级金额为多币种 JSON 不可比较）。本条与旧 EXC-BL-005（放单申请时点拦截）并存，语义为「已放单后仍未收款」。\n责任人：该订单归属的操作（operator_id）和业务。', 'P0', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         b.order_id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         COALESCE((SELECT MAX(g.biz_status_time) FROM il_order_bol_grant g\\n                   WHERE g.order_id = b.order_id AND g.del_status = 0), b.update_at) AS grant_time,\\n         DATEDIFF(NOW(), COALESCE((SELECT MAX(g.biz_status_time) FROM il_order_bol_grant g\\n                   WHERE g.order_id = b.order_id AND g.del_status = 0), b.update_at)) AS days_since_grant\\n  FROM il_order_bol b\\n  JOIN il_eco e ON e.id = b.order_id AND e.del_status = 0\\n  WHERE b.del_status = 0\\n    AND b.bol_status IN (''2'',''3'',''4'')\\n    AND EXISTS (\\n      SELECT 1 FROM il_so_container_fee_detail f\\n      WHERE f.order_id = b.order_id AND f.del_status = 0\\n        AND f.fee_type = ''1'' AND f.amount_not_written_off > 0\\n    )\\n`, $params)\\nreturn rows.filter(r => r.days_since_grant >= $params.daysAfer)\\n    .map(r => ({\\n      bizType: r.biz_type,\\n      bizId: r.biz_id,\\n      bizLabel: r.biz_label,\\n      operatorId: r.operator_id,\\n      salesmanId: r.salesman_id,\\n      title: `订单 ${r.biz_label}（${r.customer_name}）已放单 ${r.days_since_grant} 天，应收仍未核销`,\\n      anchorTime: r.grant_time,\\n      snapshot: {\\n        ecoNo: r.biz_label,\\n        customer: { id: r.customer_id, name: r.customer_name },\\n        operatorName: r.operator_name,\\n        salesmanId: r.salesman_id,\\n        grantTime: r.grant_time,\\n        daysSinceGrant: r.days_since_grant\\n      }\\n    }))"}]}', '{"daysAfer":7}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'INTERCEPT', '/fms/so/{bizId}', 0, 'v1', 1, 1, 'system', '系统初始化'),
('371596548057993216', 'EXC-BL-016', '逾期放单', 'BL', '判定：ETA − 7 天 ≤ now（eta ≤ now + 7d），订单仍未申请放单——il_order_bol 无 bol_status IN (''1'',''2'',''3'',''4'') 记录（''0''未放单/无记录均视为未申请）。\n已受理口径：il_eco.order_status NOT IN (''0'',''1'',''15'')。\n责任人：该订单归属的操作（operator_id）。\n扩展：备注15 另有 ETA−3「已发起申请放单提醒操作和财务」档，可后续以 tier 参数追加。', 'P2', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.eta AS anchor_time,\\n         DATEDIFF(e.eta, NOW()) AS lead_days\\n  FROM il_eco e\\n  WHERE e.del_status = 0\\n    AND e.eta IS NOT NULL\\n    AND e.eta <= DATE_ADD(NOW(), INTERVAL :leadDays DAY)\\n    AND e.order_status NOT IN (''0'',''1'',''15'')\\n    AND NOT EXISTS (\\n      SELECT 1 FROM il_order_bol b\\n      WHERE b.order_id = e.id AND b.del_status = 0\\n        AND b.bol_status IN (''1'',''2'',''3'',''4'')\\n    )\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  title: `订单 ${r.biz_label}（${r.customer_name}）ETA 前 ${r.lead_days} 天仍未申请放单`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    eta: r.anchor_time,\\n    leadDays: r.lead_days\\n  }\\n}))"}]}', '{"leadDays":7}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 2, 'system', '系统初始化'),
('371596548070576128', 'EXC-CUS-001', '客户超授信', 'CUS', '判定：月结客户（il_cooperating_org.settlement_method=''1''），汇总其名下已受理订单（il_eco.order_status NOT IN (''0'',''1'',''15'')）的应收未核销总额，\n超过授信额度 il_cooperating_org.line_of_credit × 百分比阈值（utilizationPct，缺省 100 即足额超限）即异常。\n未核销取费用行 il_so_container_fee_detail（fee_type=''1''、amount_not_written_off>0）按客户聚合（跨币种为近似值，见 README 值域校准）。\n责任人：该客户归属的业务（salesman_id）。', 'P1', 'ALERT', NULL, 'SCAN', '0 30 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''CUSTOMER'' AS biz_type,\\n         co.id AS biz_id, co.name AS biz_label,\\n         co.id AS customer_id, co.name AS customer_name,\\n         co.salesman_id, co.salesman_name,\\n         co.line_of_credit AS line_of_credit,\\n         IFNULL(SUM(f.amount_not_written_off), 0) AS outstanding\\n  FROM il_eco e\\n  JOIN il_cooperating_org co ON co.id = e.customer_id AND co.del_status = 0\\n  JOIN il_so_container_fee_detail f ON f.order_id = e.id\\n    AND f.del_status = 0 AND f.fee_type = ''1'' AND f.amount_not_written_off > 0\\n  WHERE e.del_status = 0\\n    AND co.settlement_method = ''1''\\n    AND e.order_status NOT IN (''0'',''1'',''15'')\\n  GROUP BY co.id, co.name, co.salesman_id, co.salesman_name, co.line_of_credit\\n`, $params)\\nreturn rows.filter(r => r.line_of_credit != null && r.line_of_credit > 0\\n    && r.outstanding > r.line_of_credit * $params.utilizationPct / 100)\\n    .map(r => ({\\n      bizType: r.biz_type,\\n      bizId: r.biz_id,\\n      bizLabel: r.biz_label,\\n      salesmanId: r.salesman_id,\\n      title: `月结客户 ${r.customer_name} 未核销 ${r.outstanding} 超授信额度 ${r.line_of_credit}`,\\n      snapshot: {\\n        customer: { id: r.customer_id, name: r.customer_name },\\n        salesman: { id: r.salesman_id, name: r.salesman_name },\\n        lineOfCredit: r.line_of_credit,\\n        outstanding: r.outstanding\\n      }\\n    }))"}]}', '{"utilizationPct":100}', '{"handlers":[{"type":"BIZ_FIELD","fields":["salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'CUSTOMER', NULL, 'STANDARD', '/fms/customer/{bizId}', 0, 'v1', 1, 3, 'system', '系统初始化'),
('371596548083159040', 'EXC-FIN-018', '进口订单结算逾期', 'FIN', '判定：进口订单（il_eco.inter_import=1），ETA − 5 天 ≤ now（eta ≤ now + 5d），存在应收未核销费用行（il_so_container_fee_detail fee_type=''1'' 且 amount_not_written_off>0），\n且其费用关系人/结算单位（settlement_unit_id）属非海桥内部公司（不在 internalUnitIds 清单内）。\n责任人：该订单归属的操作（operator_id）和业务。', 'P1', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.eta AS anchor_time,\\n         DATEDIFF(e.eta, NOW()) AS lead_days\\n  FROM il_eco e\\n  WHERE e.del_status = 0\\n    AND e.inter_import = 1\\n    AND e.eta IS NOT NULL\\n    AND e.eta <= DATE_ADD(NOW(), INTERVAL :leadDays DAY)\\n    AND EXISTS (\\n      SELECT 1 FROM il_so_container_fee_detail f\\n      WHERE f.order_id = e.id AND f.del_status = 0\\n        AND f.fee_type = ''1'' AND f.amount_not_written_off > 0\\n        AND f.settlement_unit_id IS NOT NULL\\n        AND f.settlement_unit_id NOT IN (:internalUnitIds)\\n    )\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  title: `订单 ${r.biz_label}（${r.customer_name}）进口 ETA 前 ${r.lead_days} 天，非海桥结算单位仍有未核销`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    eta: r.anchor_time,\\n    leadDays: r.lead_days\\n  }\\n}))"}]}', '{"leadDays":5,"internalUnitIds":["__REPLACE_WITH_HQ_INTERNAL_UNIT_IDS__"]}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 4, 'system', '系统初始化'),
('371596548095741952', 'EXC-ODR-001', '委托受理滞留', 'ODR', '判定：委托单产生后，基于 il_eco.etd 之后 7 天（etd ≤ now − 7d），订单仍未受理（order_status IN (''0'',''1'')，''0''草稿/''1''未受理），产生异常。\n取消单（order_status=''15''）排除；其余状态均视为已受理，不命中。\n责任人：该订单归属的操作（operator_id）和业务（该分公司业务员）。', 'P1', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.etd AS anchor_time,\\n         DATEDIFF(NOW(), e.etd) AS anchor_elapsed_days\\n  FROM il_eco e\\n  WHERE e.del_status = 0\\n    AND e.etd IS NOT NULL\\n    AND e.etd <= DATE_SUB(NOW(), INTERVAL :staleDays DAY)\\n    AND e.order_status IN (''0'',''1'')\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  title: `订单 ${r.biz_label}（${r.customer_name}）ETD 已过 ${r.anchor_elapsed_days} 天仍未受理`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    etd: r.anchor_time,\\n    elapsedDays: r.anchor_elapsed_days\\n  }\\n}))"}]}', '{"staleDays":7}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 5, 'system', '系统初始化'),
('371596548112519168', 'EXC-ODR-018', '截关前未进港', 'ODR', '判定：截关时刻 il_eco.cut_off_slip（为空则不判断），now ≥ cut_off_slip − 6h 且无进港记录（ob_portal.ot_container_status.gitm_time 为空）。\n进港时间以 ob_portal.ot_container_status.gitm_time 为准（按 bill_no=mbl_no + container_no 关联）。\n恢复：进港（gitm_time 写入）或超回看窗口。\n口径：本条与旧 EXC-ODR-002 并存，差异——截关列取 cut_off_slip、提前量 6h、不引入 cy_closing_time 回退与 R7 离港兜底。\n责任人：该订单归属的操作（operator_id）。', 'P0', 'ALERT', NULL, 'SCAN', '0 0/15 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.cut_off_slip AS cut_off_time,\\n         TIMESTAMPDIFF(HOUR, NOW(), e.cut_off_slip) AS hours_to_cut,\\n         cs.gitm_time AS gitm_time,\\n         e.cut_off_slip AS anchor_time\\n  FROM il_eco e\\n  LEFT JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.cut_off_slip IS NOT NULL\\n    AND e.container_no IS NOT NULL AND TRIM(e.container_no) <> ''''\\n    AND e.cut_off_slip <= DATE_ADD(NOW(), INTERVAL :leadHours HOUR)\\n    AND e.cut_off_slip >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n`, $params)\\nreturn rows.filter(r => r.gitm_time == null && r.hours_to_cut <= $params.leadHours)\\n    .map(r => ({\\n      bizType: r.biz_type,\\n      bizId: r.biz_id,\\n      bizLabel: r.biz_label,\\n      operatorId: r.operator_id,\\n      salesmanId: r.salesman_id,\\n      title: `订单 ${r.biz_label}（${r.customer_name}）截关前 ${r.hours_to_cut} 小时仍未进港`,\\n      anchorTime: r.anchor_time,\\n      snapshot: {\\n        ecoNo: r.biz_label,\\n        customer: { id: r.customer_id, name: r.customer_name },\\n        operatorName: r.operator_name,\\n        salesmanId: r.salesman_id,\\n        cutOffTime: r.cut_off_time,\\n        hoursToCut: r.hours_to_cut\\n      }\\n    }))"}]}', '{"leadHours":6,"lookbackDays":2}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_002_017', 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 6, 'system', '系统初始化');
